package com.sigtm.backend.service;
import com.sigtm.backend.dto.TableroAbastecimientoResponse; import com.sigtm.backend.model.*; import com.sigtm.backend.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service @RequiredArgsConstructor public class TableroAbastecimientoService {private final ProductoRepository products;private final SolicitudCompraRepository requests;private final OrdenCompraRepository orders;private final FacturaProveedorRepository invoices;private final SeguimientoCompraRepository tracking;private final EvaluacionProveedorRepository evaluations;
 @Transactional(readOnly=true) public TableroAbastecimientoResponse obtener(){long critical=products.findByActiveTrue().stream().filter(p->p.getCurrentStock()<=p.getMinStock()).count();long pendingRequests=requests.findAll().stream().filter(s->"PENDIENTE".equals(s.getStatus())).count();long pendingOrders=orders.findAll().stream().filter(o->Set.of("PENDIENTE_APROBACION","PENDIENTE","PARCIAL").contains(o.getStatus())).count();long delayed=orders.findAll().stream().filter(o->tracking.findByPurchaseOrderId(o.getId()).map(t->"DEMORADA".equals(t.getStatus())).orElse(false)).count();BigDecimal debt=invoices.findAll().stream().map(FacturaProveedor::getBalance).reduce(BigDecimal.ZERO,BigDecimal::add);List<Map<String,Object>> actions=new ArrayList<>();if(critical>0)actions.add(Map.of("type","REPOSICION","message",critical+" productos requieren reposición"));if(delayed>0)actions.add(Map.of("type","LOGISTICA","message",delayed+" entregas están demoradas"));if(debt.signum()>0)actions.add(Map.of("type","PAGOS","message","Existen cuentas por pagar abiertas"));return new TableroAbastecimientoResponse(critical,pendingRequests,pendingOrders,delayed,debt,List.of(),actions);}}
